function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function toast(m){let t=$('#toast');t.textContent=m;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2400)}async function api(url,opt={}){let r=await fetch(url,{headers:{'Content-Type':'application/json',...(opt.headers||{})},...opt}),d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||'Request failed');return d}
function isPizza(p){const c=(p.publicCategory&&p.publicCategory!=='category'&&p.publicCategory!=='all')?p.publicCategory:p.category;return p.section==='fastfood'&&['pizza','pizza-all','regular-pizza','special-pizza','stuffed-pizza'].includes(c)}
