function isPasta(p){const c=(p.publicCategory&&p.publicCategory!=='category'&&p.publicCategory!=='all')?p.publicCategory:p.category;return p.section==='fastfood'&&c==='pasta'}
function isFries(p){const c=String((p.publicCategory&&p.publicCategory!=='category'&&p.publicCategory!=='all')?p.publicCategory:p.category).toLowerCase().replace(/[^a-z]/g,'');return p.section==='fastfood'&&['fries','frenchfries','frenchfry'].includes(c)}
function pastaPrices(p){const v=p.sizePrices||{};const full=Number(v.full)>0?Number(v.full):Math.max(0,Number(p.price)||0);return {full,half:Number(v.half)>0?Number(v.half):Math.round(full*.6/10)*10}}
