function showCustomerOrderNotice(message){const box=$('#customerOrderNotice');if(!box||!message)return;box.textContent=message;box.hidden=false;box.dataset.visible='1';box.setAttribute('tabindex','-1');try{sessionStorage.setItem('fiveStarCustomerOrderNotice',message)}catch{} }
let orderSuccessTimer=null;function showOrderSuccessToast(){const box=$('#customerOrderNotice');if(!box)return;clearTimeout(orderSuccessTimer);try{sessionStorage.removeItem('fiveStarCustomerOrderNotice')}catch{}box.classList.remove('shop-closed-warning');box.classList.add('order-success-toast');box.innerHTML='<span class="order-success-check" aria-hidden="true"><span>✓</span></span><span class="order-success-message">Your order has been successfully placed.</span>';box.hidden=false;box.dataset.visible='1';box.removeAttribute('tabindex');orderSuccessTimer=setTimeout(()=>{box.hidden=true;box.classList.remove('order-success-toast');box.replaceChildren()},4500)}
async function syncCustomerOrders(){let orders=[];try{orders=JSON.parse(localStorage.getItem('fiveStarCustomerOrders')||'[]')}catch{};let changed=false;const missingIds=new Set();for(const o of orders){try{const r=await api('/api/orders/'+encodeURIComponent(o.id)+'/status');const fresh=r.order;if(fresh.status!==o.status||fresh.cancelReason!==o.cancelReason||fresh.cancelledAt!==o.cancelledAt||fresh.cancelledBy!==o.cancelledBy){if(fresh.status!==o.status){const msg=fresh.status==='cancelled'?'Your order '+o.id+' was cancelled'+(fresh.cancelReason?'. Reason: '+fresh.cancelReason:'')+'.':fresh.status==='completed'?'Your order '+o.id+' has been completed.':'';if(msg){toast(msg);if(fresh.status==='cancelled')showCustomerOrderNotice(msg);try{if('Notification'in window&&Notification.permission==='granted')new Notification('Five Star order update',{body:msg,requireInteraction:fresh.status==='cancelled'});const C=window.AudioContext||window.webkitAudioContext;if(C){window.__customerOrderAudio=window.__customerOrderAudio||new C();const ctx=window.__customerOrderAudio;if(ctx.state==='suspended')ctx.resume();const tones=fresh.status==='completed'?[740,988]:[660,520];tones.forEach((hz,i)=>{const osc=ctx.createOscillator(),gain=ctx.createGain(),t=ctx.currentTime+i*.16;osc.type='sine';osc.frequency.value=hz;gain.gain.setValueAtTime(.0001,t);gain.gain.exponentialRampToValueAtTime(.09,t+.02);gain.gain.exponentialRampToValueAtTime(.0001,t+.13);osc.connect(gain);gain.connect(ctx.destination);osc.start(t);osc.stop(t+.14)})}}catch{}}}Object.assign(o,fresh);o.updatedAt=new Date().toISOString();changed=true}}catch(err){if(String(err.message||'').includes('404')||String(err.message||'').toLowerCase().includes('not found')){missingIds.add(o.id);changed=true}}}if(changed){localStorage.setItem('fiveStarCustomerOrders',JSON.stringify(orders.filter(o=>!missingIds.has(o.id)&&o.status!=='completed'&&!(o.status==='cancelled'&&o.cancelledAt&&Date.now()-Date.parse(o.cancelledAt)>15*60*1000))));renderCustomerOrderCards();}}
